"""The stored summary record. Summaries are not generated by the live pipeline; the schema and loader keep the record so earlier runs still load."""

from __future__ import annotations

from pydantic import Field

from app.ingestion.contracts import SourceSpan, StrictRecord
from app.models.client import ModelSpec, ModelUsage


class Summary(StrictRecord):
    document_id: str
    run_id: str
    source_sha256: str
    level: str
    summary: str = Field(min_length=1)
    chunk_ids: list[str]
    source_spans: list[SourceSpan]
    child_artifact_ids: list[str] = Field(default_factory=list)
    model: ModelSpec
    prompt_version: str
    usage: ModelUsage
